$pids=29504,14220; foreach($p in $pids){ $proc=Get-Process -Id $p -ErrorAction SilentlyContinue; if($proc){ Write-Output "PID $p -> $($proc.Path)" } }
Write-Output "---- jar files ----"
Get-ChildItem 'D:\repository\苏住房后端\service-expand\service-expand-server\target\*.jar','D:\repository\苏住房后端\common-framework\common-framework-server\target\*.jar' -ErrorAction SilentlyContinue | Select-Object FullName, Length, LastWriteTime

$tmp="$env:TEMP\bootcfg_check"; Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue; New-Item -ItemType Directory -Path $tmp | Out-Null
Add-Type -AssemblyName System.IO.Compression.FileSystem
function Get-BootFromJar($jar,$name){
  $zip=[System.IO.Compression.ZipFile]::OpenRead($jar)
  $e=$zip.Entries | Where-Object { $_.FullName -eq 'BOOT-INF/classes/bootstrap.yml' -or $_.FullName -eq 'bootstrap.yml' -or $_.FullName -eq 'WEB-INF/classes/bootstrap.yml' }
  if($e){
    $sr=New-Object System.IO.StreamReader($e.Open())
    $c=$sr.ReadToEnd(); $sr.Close()
    Write-Output "=== $name : $($e.FullName) ==="
    ($c -split "`n") | Where-Object { $_ -match 'active|profiles' }
  } else { Write-Output "=== $name : no bootstrap entry found ===" ; $zip.Entries | Where-Object {$_.FullName -match 'bootstrap'} | Select-Object -First 10 FullName }
  $zip.Dispose()
}
Get-BootFromJar 'D:\repository\苏住房后端\service-expand\service-expand-server\target\service-expand-server.jar' 'service-expand'
Get-BootFromJar 'D:\repository\苏住房后端\common-framework\common-framework-server\target\common-framework-server.jar' 'common-framework'

$p=Get-CimInstance Win32_Process -Filter "ProcessId=14220"; $p.CommandLine; if($p.CommandLine -match 'service-expand-server\.jar'){ Stop-Process -Id 14220 -Force; Write-Output "STOPPED 14220" } else { Write-Output "PID mismatch, NOT killing" }
Start-Sleep -Seconds 2
Get-Process -Id 14220 -ErrorAction SilentlyContinue | Select-Object Id
